return items.map(item => {

  const json = item.json;

  // Detect attachments
  const hasAttachments =
    json.payload?.mimeType?.includes('multipart') || false;

  return {
    json: {
      source_type: 'gmail',

      email_subject: json.Subject || '',

      email_from: json.From || '',

      email_date: json.internalDate
        ? new Date(Number(json.internalDate)).toISOString()
        : null,

      gmail_message_id: json.id || '',

      gmail_thread_id: json.threadId || '',

      email_text_preview: json.snippet || '',

      has_attachments: hasAttachments,

      attachment_count: hasAttachments ? 1 : 0,

      gmail_labels: (json.labels || []).map(label => label.name),

      raw_email_data: json
    }
  };
});

return items.map(item => {

  const json = item.json;

  return {
    json: {
      ...json,

      // OCR metadata
      ocr_status: 'required',

      parse_warning: 'OCR required for scanned PDF',

      // Keep workflow alive with fallback text
      final_text:
        json.extracted_text ||
        json.email_text_preview ||
        'No readable text found'
    }
  };
});

return items.map(item => {

  const json = item.json;

  // PDF extracted text
  const pdfText = json.text;

  // OCR fallback text
  const ocrText = json.final_text;

  // Email body text from previous node
  const emailText =
    $(' Fetch Email Attachment Content').first()?.json?.text ||
    json.email_text_preview ||
    '';

  // Choose best available text
  let finalText = '';

  if (pdfText && pdfText.trim().length > 100) {
    finalText = pdfText;
  } else if (emailText && emailText.trim().length > 20) {
    finalText = emailText;
  } else if (ocrText && ocrText.trim().length > 20) {
    finalText = ocrText;
  } else {
    finalText = 'No readable content found';
  }

  // Detect source type
  let sourceSummary = '';

  if (pdfText && pdfText.trim().length > 100) {
    sourceSummary = 'Using extracted PDF text';
  } else if (emailText && emailText.trim().length > 20) {
    sourceSummary = 'Using email body text';
  } else if (ocrText && ocrText.trim().length > 20) {
    sourceSummary = 'Using OCR fallback text';
  } else {
    sourceSummary = 'No readable text source available';
  }

  return {
    json: {
      ...json,

      // Final unified text
      final_text: finalText,

      // Helpful metadata
      source_file_name:
        json.fileName ||
        json.filename ||
        'email_content.txt',

      source_summary_line: sourceSummary,

      final_text_length: finalText.length
    }
  };
});

const finalText = $json.final_text || '';

// Normalize text heavily
const cleaned = finalText
  .substring(0, 1000)
  .replace(/\s+/g, ' ')
  .replace(/[^a-zA-Z0-9 ]/g, '')
  .trim()
  .toLowerCase();

// Simple stable hash
let hash = 0;

for (let i = 0; i < cleaned.length; i++) {
  const char = cleaned.charCodeAt(i);
  hash = ((hash << 5) - hash) + char;
  hash |= 0;
}

const circular_hash = `circular_${Math.abs(hash)}`;

return [
  {
    json: {
      ...$json,
      circular_hash,
      fingerprint_preview: cleaned.substring(0, 250)
    }
  }
];

// Get Gemini raw response text
const rawText =
  $json.content?.parts?.[0]?.text || '{}';

let parsed = {};

try {
  parsed = JSON.parse(rawText);
} catch (error) {

  // fallback if invalid JSON
  parsed = {
    parse_error: true,
    raw_response: rawText
  };
}

// Return clean structured JSON
return [
  {
    json: {
      ...parsed,

      // Keep original metadata if needed
      ai_raw_response: rawText,

      processed_at: new Date().toISOString()
    }
  }
];
